class Solution:
    def smallestNumber(self, n: int, t: int) -> int:
        for x in range(n, 100):
            product = 1
            for d in str(x):
                product *= int(d)
            if product % t == 0:
                return x
        return -1

class Solution:
    def smallestNumber(self, n: int, t: int) -> int:
        x = n
        while True:
            product = 1
            y = x
            while y > 9:
                product *= y % 10
                y //= 10
            if product % t == 0:
                return x
            x += 1

